harness:
#include <iomanip>
#include <iostream>

struct Vector2D
{
    double x;
    double y;
};

Vector2D operator+(const Vector2D& a, const Vector2D& b);

int main()
{
    int n;
    while (std::cin >> n)
    {
        Vector2D total{0, 0};
        for (int i = 0; i < n; i++)
        {
            Vector2D v;
            std::cin >> v.x >> v.y;
            total = total + v;
        }
        std::cout << std::fixed << std::setprecision(2)
                  << total.x << " " << total.y << "\n";
    }
    return 0;
}

