"""Random lists of 2D vectors with two-decimal-place components, including
negatives and an empty list."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 8)
    vectors = [(round(rng.uniform(-20, 20), 2), round(rng.uniform(-20, 20), 2))
               for _ in range(n)]
    lines = [str(n)] + ["%.2f %.2f" % v for v in vectors]
    return {"name": "%d random 2D vectors #%d" % (n, index),
            "stdin": " ".join(lines) + "\n"}
